from solution import retry_with_backoff

def test_success_on_first_try():
    """Verify it returns immediately if the function succeeds."""
    calls = []
    def fn():
        calls.append(1)
        return "success"

    result = retry_with_backoff(fn, max_attempts=3)
    assert result == "success"
    assert len(calls) == 1

def test_success_after_retry():
    """Verify it returns successfully if it succeeds within max_attempts."""
    calls = []
    def fn():
        calls.append(1)
        if len(calls) < 2:
            raise ValueError("fail")
        return "success"

    result = retry_with_backoff(fn, max_attempts=3)
    assert result == "success"
    assert len(calls) == 2

def test_max_attempts_reached():
    """Verify it raises the error after exactly max_attempts."""
    calls = []
    def fn():
        calls.append(1)
        raise ValueError("permanent failure")

    max_tries = 3
    try:
        retry_with_backoff(fn, max_attempts=max_tries)
    except ValueError as e:
        assert str(e) == "permanent failure"
        assert len(calls) == max_tries
    else:
        raise AssertionError("Expected ValueError was not raised")

def test_zero_max_attempts():
    """Verify behavior when max_attempts is 0 (should fail immediately)."""
    def fn():
        raise ValueError("fail")

    try:
        retry_with_backoff(fn, max_attempts=0)
    except ValueError as e:
        assert str(e) == "fail"
    else:
        raise AssertionError("Expected ValueError was not raised")

def test_re_raises_original_exception():
    """Verify the exception type and message are preserved."""
    def fn():
        raise TypeError("type error")

    try:
        retry_with_backoff(fn, max_attempts=1)
    except TypeError as e:
        assert str(e) == "type error"
    except Exception as e:
        raise AssertionError(f"Wrong exception type: {type(e)}")

def test_no_extra_sleep_on_final_failure():
    """
    Verify the requirement 're-raise the final error without a final sleep'.
    While we can't easily check 'time', we ensure the logic doesn't 
    accidentally increment attempt count beyond max_attempts.
