    total = 0
    prev_val = 0

    # Iterate backwards through the string
    for char in reversed(s):
        curr_val = vals[char]
        if curr_val < prev_val:
            total -= curr_val
        else:
            total += curr_val
        prev_val = curr_val

    return total

